1	/**
2	 * Application source migration for an Angular CLI era workspace.
3	 *
4	 * Two shapes are handled, both of them defined by Angular and its runtime
5	 * dependencies rather than by any application:
6	 *
7	 * - Deep `zone.js/dist/*` specifiers. zone.js 0.11 replaced the `dist`
8	 *   directory layout the Angular CLI's generated `polyfills.ts` and `test.ts`
9	 *   import from with package entry points, so a workspace generated before it
10	 *   names files that no longer exist on a modern line and fails to resolve.
11	 * - Testing symbols `@angular/core/testing` renamed and then removed, of which
12	 *   `async` — renamed to `waitForAsync` because it collided with the
13	 *   ECMAScript keyword — is the one this table carries.
14	 *
15	 * Every rewrite rides the parsed module rather than the text: only the source
16	 * literal of an `import`/`export … from` declaration is edited, so a matching
17	 * string inside a comment, a template, or an ordinary expression is left
18	 * exactly where it is. A commented-out `import 'zone.js/dist/zone-error'` — a
19	 * line the Angular CLI itself generates into `src/environments/environment.ts`
20	 * — is therefore not touched, which a textual substitution would get wrong.
21	 */
22	
23	import { analyze } from 'yuku-analyzer';
24	import { compareStrings } from './angular-target-cell.ts';
25	
26	/**
27	 * zone.js's package entry points, keyed by the `dist` path they replaced. The
28	 * bundle files under `dist` were the public surface before 0.11; afterwards the
29	 * same code is reachable only through these specifiers.
30	 */
31	export const ZONE_JS_SPECIFIER_REPLACEMENTS: Readonly<Record<string, string>> = Object.freeze({
32		'zone.js/dist/long-stack-trace-zone': 'zone.js/plugins/long-stack-trace-zone',
33		'zone.js/dist/task-tracking': 'zone.js/plugins/task-tracking',
34		'zone.js/dist/webapis-media-query': 'zone.js/plugins/webapis-media-query',
35		'zone.js/dist/zone': 'zone.js',
36		'zone.js/dist/zone-error': 'zone.js/plugins/zone-error',
37		'zone.js/dist/zone-patch-rxjs': 'zone.js/plugins/zone-patch-rxjs',
38		'zone.js/dist/zone-testing': 'zone.js/testing',
39	});
40	
41	/**
42	 * Renamed exports, keyed by module specifier and then by the removed export
43	 * name. The rewrite keeps the local binding name the module already uses
44	 * (`import { waitForAsync as async }`), so no call site changes and no scope
45	 * analysis is required to be correct. It does not modernise call-site naming:
46	 * a module that used `async(...)` still reads `async(...)` afterwards, and this
47	 * capability claims nothing more than that the removed export is no longer
48	 * requested.
49	 */
50	export const RENAMED_MODULE_EXPORTS: Readonly<Record<string, Readonly<Record<string, string>>>> =
51		Object.freeze({
52			'@angular/core/testing': Object.freeze({ async: 'waitForAsync' }),
53		});
54	
55	/**
56	 * RxJS's own package restructure, keyed by the RxJS 5 deep entry point it
57	 * replaced. RxJS 5 published one module per exported type at the package root
58	 * — `rxjs/Observable`, `rxjs/Subject` and their siblings — and RxJS 6 collapsed
59	 * every one of them into the package's own root export. The deep paths were not
60	 * moved: they no longer exist, so a module that imports one does not resolve on
61	 * any line at or beyond 6.
62	 *
63	 * Every entry here is a name RxJS re-exports from the package root, checked
64	 * against the `rxjs` 7.8 type surface rather than remembered: the rewrite is
65	 * only correct if the binding the module already names is reachable from
66	 * `'rxjs'`, and a type whose deep module went away *without* a root export
67	 * would be a removal for a caller to answer, not a specifier to rewrite.
68	 */
69	export const RXJS_SIX_SPECIFIER_REPLACEMENTS: Readonly<Record<string, string>> = Object.freeze({
70		'rxjs/AsyncSubject': 'rxjs',
71		'rxjs/BehaviorSubject': 'rxjs',
72		'rxjs/ConnectableObservable': 'rxjs',
73		'rxjs/Notification': 'rxjs',
74		'rxjs/Observable': 'rxjs',
75		'rxjs/Observer': 'rxjs',
76		'rxjs/Operator': 'rxjs',
77		'rxjs/ReplaySubject': 'rxjs',
78		'rxjs/Scheduler': 'rxjs',
79		'rxjs/Subject': 'rxjs',
80		'rxjs/Subscriber': 'rxjs',
81		'rxjs/Subscription': 'rxjs',
82	});
83	
84	/**
85	 * The RxJS 5 patch-import prefix. `import 'rxjs/add/operator/map'` installed an
86	 * operator onto `Observable.prototype` as a side effect, and RxJS 6 removed
87	 * both the module and the prototype patching it performed.
88	 *
89	 * This capability does not rewrite these imports, and the refusal is the point.
90	 * Deleting the import is only half the edit: the `.map(…)` and `.catch(…)`
91	 * call sites it enabled are method calls on an observable, and turning them
92	 * into `.pipe(map(…), catchError(…))` is a call-site rewrite across every
93	 * module that inherited the patched prototype — not a specifier substitution.
94	 * A half-applied patch removal produces a tree that compiles nowhere and hides
95	 * why, so each patch import is reported by name instead.
96	 */
97	export const RXJS_PATCH_IMPORT_PREFIX = 'rxjs/add/';
98	
99	/** Era module specifiers this capability rewrites, from every table it carries. */
100	export const ERA_SPECIFIER_REPLACEMENTS: Readonly<Record<string, string>> = Object.freeze({
101		...ZONE_JS_SPECIFIER_REPLACEMENTS,
102		...RXJS_SIX_SPECIFIER_REPLACEMENTS,
103	});
104	
105	export type SourceChange = Readonly<{
106		kind: 'module-specifier' | 'renamed-export';
107		line: number;
108		from: string;
109		to: string;
110	}>;
111	
112	export type SourceMigration = Readonly<{
113		path: string;
114		source: string;
115		changed: boolean;
116		changes: readonly SourceChange[];
117		unhandled: readonly string[];
118	}>;
119	
120	type Edit = Readonly<{ start: number; end: number; text: string; change: SourceChange }>;
121	
122	type SourceSpan = readonly [number, number];
123	
124	type SourceLiteral = Readonly<{ value: string; span: SourceSpan }>;
125	
126	type ImportSpecifierNode = Readonly<{
127		type: string;
128		imported?: Readonly<{ type: string; name?: string }>;
129		local?: Readonly<{ name: string }>;
130	}>;
131	
132	/**
133	 * The half-open source span of a node. The parser reports `start`/`end`; the
134	 * ESTree `range` pair is accepted as well so the capability does not depend on
135	 * which of the two spellings a parser build emits.
136	 */
137	function spanOf(node: unknown): SourceSpan | null {
138		if (typeof node !== 'object' || node === null) return null;
139		const candidate = node as { start?: unknown; end?: unknown; range?: unknown };
140		if (typeof candidate.start === 'number' && typeof candidate.end === 'number')
141			return [candidate.start, candidate.end];
142		const range = candidate.range;
143		if (!Array.isArray(range) || range.length < 2) return null;
144		const [start, end] = range as readonly unknown[];
145		return typeof start === 'number' && typeof end === 'number' ? [start, end] : null;
146	}
147	
148	type DeclarationNode = Readonly<{
149		type: string;
150		source?: unknown;
151		specifiers?: readonly unknown[];
152		importKind?: string;
153	}>;
154	
155	function sourceLiteral(node: unknown): SourceLiteral | null {
156		if (typeof node !== 'object' || node === null) return null;
157		const candidate = node as { value?: unknown };
158		if (typeof candidate.value !== 'string') return null;
159		const span = spanOf(node);
160		return span === null ? null : { value: candidate.value, span };
161	}
162	
163	function importSpecifier(node: unknown): ImportSpecifierNode | null {
164		if (typeof node !== 'object' || node === null) return null;
165		const candidate = node as ImportSpecifierNode;
166		return typeof candidate.type === 'string' ? candidate : null;
167	}
168	
169	/**
170	 * Requote a replacement specifier the way the original literal was written, so
171	 * a rewritten import keeps the file's quote style and the diff stays confined
172	 * to the specifier itself. An unrecognised opening quote falls back to a JSON
173	 * string, which is always valid.
174	 */
175	function quoteLike(original: string, replacement: string): string {
176		const quote = original.slice(0, 1);
177		if (
178			(quote !== "'" && quote !== '"') ||
179			replacement.includes(quote) ||
180			replacement.includes('\\')
181		)
182			return JSON.stringify(replacement);
183		return `${quote}${replacement}${quote}`;
184	}
185	
186	function lineOf(source: string, offset: number): number {
187		return source.slice(0, offset).split('\n').length;
188	}
189	
190	/**
191	 * Rewrite one module's era specifiers and renamed imports. A module with
192	 * nothing to rewrite is returned byte-identical, with `changed` false.
193	 *
194	 * A module that does not parse is a hard failure naming the file and the
195	 * diagnostics, never a silent skip: a skipped file would be counted as
196	 * unchanged, and an uncounted file is exactly the defect a migration record
197	 * exists to rule out.
198	 */
199	export function migrateAngularSourceModule(path: string, source: string): SourceMigration {
200		const analyzed = analyze(source, { path, lang: path.endsWith('.ts') ? 'ts' : 'js' });
201		const errors = analyzed.diagnostics.filter((entry) => entry.severity === 'error');
202		if (errors.length > 0)
203			throw new Error(
204				`Angular source migration: ${path} does not parse, so its era shapes cannot be ` +
205					`rewritten and it cannot be honestly counted as unchanged. Diagnostics: ` +
206					errors.map((entry) => entry.message).join('; '),
207			);
208		const edits: Edit[] = [];
209		const unhandled: string[] = [];
210		for (const statement of analyzed.ast.body as readonly unknown[]) {
211			const declaration = statement as DeclarationNode;
212			if (
213				declaration.type !== 'ImportDeclaration' &&
214				declaration.type !== 'ExportNamedDeclaration' &&
215				declaration.type !== 'ExportAllDeclaration'
216			)
217				continue;
218			const literal = sourceLiteral(declaration.source);
219			if (literal === null) continue;
220			if (literal.value.startsWith(RXJS_PATCH_IMPORT_PREFIX)) {
221				unhandled.push(
222					`${path} imports ${literal.value}, an RxJS 5 patch module that RxJS 6 removed along ` +
223						`with the prototype patching it performed. Removing the import alone would leave ` +
224						`the operator call sites it enabled calling a method that no longer exists, so it ` +
225						`is reported rather than rewritten: the call sites have to move to \`pipe\` first.`,
226				);
227				continue;
228			}
229			const replacement = ERA_SPECIFIER_REPLACEMENTS[literal.value];
230			if (replacement !== undefined)
231				edits.push({
232					start: literal.span[0],
233					end: literal.span[1],
234					text: quoteLike(source.slice(literal.span[0], literal.span[1]), replacement),
235					change: {
236						kind: 'module-specifier',
237						line: lineOf(source, literal.span[0]),
238						from: literal.value,
239						to: replacement,
240					},
241				});
242			const renames = RENAMED_MODULE_EXPORTS[literal.value];
243			if (renames === undefined) continue;
244			for (const node of declaration.specifiers ?? []) {
245				const specifier = importSpecifier(node);
246				if (specifier === null || specifier.type !== 'ImportSpecifier') continue;
247				const imported = specifier.imported;
248				if (imported === undefined || imported.type !== 'Identifier') continue;
249				const name = imported.name;
250				if (name === undefined) continue;
251				const renamed = renames[name];
252				if (renamed === undefined) continue;
253				const local = specifier.local?.name ?? name;
254				const span = spanOf(node);
255				if (span === null) continue;
256				edits.push({
257					start: span[0],
258					end: span[1],
259					text: `${renamed} as ${local}`,
260					change: {
261						kind: 'renamed-export',
262						line: lineOf(source, span[0]),
263						from: `${name} as ${local}`,
264						to: `${renamed} as ${local}`,
265					},
266				});
267			}
268		}
269		for (const [specifier] of Object.entries(ZONE_JS_SPECIFIER_REPLACEMENTS))
270			if (source.includes(`import(`) && source.includes(specifier))
271				unhandled.push(
272					`${path} may reach ${specifier} through a dynamic import, which this capability does not rewrite`,
273				);
274		const ordered = [...edits].sort((left, right) => right.start - left.start);
275		let migrated = source;
276		for (const edit of ordered)
277			migrated = `${migrated.slice(0, edit.start)}${edit.text}${migrated.slice(edit.end)}`;
278		const changes = [...edits]
279			.sort((left, right) => left.start - right.start)
280			.map((edit) => edit.change);
281		return Object.freeze({
282			path,
283			source: migrated,
284			changed: migrated !== source,
285			changes: Object.freeze(changes),
286			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
287		});
288	}
